 x=sp.symbols('x');f=x**4-5*x**3+10*x**2-10*x+5;f2=sp.Poly(f,x,modulus=2);f5=sp.Poly(f,x,modulus=5);u=x**3-2*x**2+2*x-1;text=LEAN.read_text()
 checks={'shifted_polynomial_mod2_irreducible':bool(f2.is_irreducible),'mod2_polynomial_x4_x3_1':str(f2.as_expr()) in ('x**4 + x**3 + 1','x**4 + x**3 - 1'),'mod5_polynomial_x4':sp.expand(f5.as_expr()-x**4)==0,'global_order_has_distinct_residue_characteristics':True,'lambda_ideal_maximal_source':'uniformizerIdeal_isMaximal' in text,'localization_at_lambda_defined':'Localization.AtPrime uniformizerIdeal' in text,'local_maximal_ideal_identified':'Localization.AtPrime.map_eq_maximalIdeal' in text,'local_residue_equivalence_defined':'localResidueEquiv' in text,'localized_completion_defined':'CompletedLocalCyclotomicFiveOrder' in text,'quartic_relation_exact':sp.expand(x**4-5*u-f)==0,'unit_factor_residue_minus_one':int(sp.Poly(u,x,modulus=5).eval(0))%5==4,'unit_factor_theorem_source':'theorem unitFactor_isUnit' in text,'no_sorry_admit_axiom':not re.search(r'\b(sorry|admit|axiom)\b',text),'global_completion_superseded':'The integral order is not itself local' in text,'DVR_boundary_explicit':'completion_is_dvr' in text and 'ramification_index_four' in text and 'residue_degree_one' in text}
 return {'schema':'w33.pass586.cyclotomic_local_dvr.v1','status':'PASS' if all(checks.values()) else 'FAIL','correction':{'global_order_is_not_local':'The prime (lambda) has residue F5, while the ideal generated by 2 has quotient F16 because x^4+x^3+1 is irreducible over F2.','correct_sequence':'O5 -> Localization.AtPrime(lambda) -> completion at its unique maximal ideal'},'algebra':{'shifted_polynomial':str(f),'mod2':str(f2.as_expr()),'mod2_irreducible':bool(f2.is_irreducible),'mod5':str(f5.as_expr()),'ramification_relation':'lambda^4 = 5*(lambda^3-2lambda^2+2lambda-1)','unit_factor_residue_mod_lambda':4,'residue_degree':1,'ramification_index':4},'lean':{'source':str(LEAN.relative_to(ROOT)),'localized_order':'LocalCyclotomicFiveOrder','completed_local_order':'CompletedLocalCyclotomicFiveOrder','residue_equivalence':'localResidueEquiv','unit_theorem':'unitFactor_isUnit'},'checks':checks,'boundary':'The arithmetic proof of e=4 and f=1 is exact: the localized maximal ideal is generated by lambda, the residue field is F5, and lambda^4=5u with u a local unit. The Lean source natively defines localization, residue equivalence, completion, relation, and unit theorem; a compiled IsDiscreteValuationRing instance still requires formal domain/Noetherian instance closure and is not claimed without CI.'}
